from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse
import csv
import io
import json
import sqlite3

ROOT = Path(__file__).resolve().parent
DB_PATH = ROOT / "portal.db"


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == "/api/health":
            return self.send_obj(200, {"status": "ok"})
        if parsed.path == "/api/metrics/summary":
            return self.metrics_summary(parse_qs(parsed.query))
        if parsed.path == "/api/incidents":
            return self.incidents(parse_qs(parsed.query))
        if parsed.path == "/api/incidents/export":
            return self.incident_export(parse_qs(parsed.query))
        if parsed.path == "/":
            return self.send_file(ROOT / "templates/layout.html", "text/html; charset=utf-8")
        if parsed.path == "/static/app.js":
            return self.send_file(ROOT / "static/app.js", "application/javascript; charset=utf-8")
        return self.send_obj(404, {"error": "not_found"})

    @staticmethod
    def matching_incidents(severity):
        with sqlite3.connect(DB_PATH) as conn:
            conn.row_factory = sqlite3.Row
            return [dict(row) for row in conn.execute(
                """SELECT incident_id, service, severity, status, created_at
                   FROM incidents
                   WHERE severity = ? COLLATE NOCASE
                   ORDER BY created_at DESC""",
                (severity,),
            ).fetchall()]

    def incidents(self, query):
        values = query.get("severity", [])
        if len(values) != 1 or values[0] == "":
            return self.send_obj(400, {"error": "severity_required"})
        return self.send_obj(200, self.matching_incidents(values[0]))

    def incident_export(self, query):
        values = query.get("severity", [])
        if len(values) != 1 or values[0] == "":
            return self.send_obj(400, {"error": "severity_required"})
        columns = ("incident_id", "service", "severity", "status", "created_at")
        output = io.StringIO(newline="")
        writer = csv.writer(output)
        writer.writerow(columns)
        writer.writerows(tuple(row[column] for column in columns)
                         for row in self.matching_incidents(values[0]))
        data = output.getvalue().encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/csv; charset=utf-8")
        self.send_header("Content-Disposition", 'attachment; filename="incidents.csv"')
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def metrics_summary(self, query):
        start = query.get("start", [None])[0]
        end = query.get("end", [None])[0]
        if not self.valid_date(start) or not self.valid_date(end):
            return self.send_obj(400, {"error": "start and end must be YYYY-MM-DD dates"})
        if start > end:
            return self.send_obj(400, {"error": "start must be on or before end"})

        with sqlite3.connect(DB_PATH) as conn:
            avg_latency, total_requests, error_requests = conn.execute(
                """SELECT AVG(latency_ms), COALESCE(SUM(total_requests), 0),
                          COALESCE(SUM(error_requests), 0)
                   FROM metrics_daily
                   WHERE day IS NOT NULL AND latency_ms IS NOT NULL
                     AND day >= ? AND day <= ?""",
                (start, end),
            ).fetchone()
        error_rate = (error_requests / total_requests * 100) if total_requests else 0
        return self.send_obj(200, {
            "avg_latency_ms": round(avg_latency or 0, 2),
            "total_requests": total_requests,
            "error_rate_pct": round(error_rate, 2),
        })

    @staticmethod
    def valid_date(value):
        if not isinstance(value, str):
            return False
        try:
            return datetime.strptime(value, "%Y-%m-%d").strftime("%Y-%m-%d") == value
        except ValueError:
            return False

    def send_obj(self, status, obj):
        data = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def send_file(self, path, kind):
        try:
            data = path.read_bytes()
        except OSError:
            return self.send_obj(404, {"error": "missing_asset"})
        self.send_response(200)
        self.send_header("Content-Type", kind)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, *args):
        pass


